detail.command:
echo '--- bundle content probes ---'; for s in green-hills space-station RigidBody rapier MatchManager BotPlanner HoleSceneBuilder CameraController ballStopThreshold powerExponent Hud Scoreboard; do printf '%-20s %s
' "$s" "$(grep -rlo "$s" dist/assets/*.js 2>/dev/null | wc -l | tr -d ' ')"; done; echo '--- dist files ---'; ls -la dist/assets; echo '--- dev server ---'; (npx vite --port 5199 >/tmp/vite.log 2>&1 &) ; sleep 6; curl -s -o /tmp/page.html -w 'HTTP %{http_code}
' http://localhost:5199/; curl -s -o /dev/null -w 'MAIN %{http_code}
' http://localhost:5199/src/main.ts; head -5 /tmp/vite.log; pkill -f 'vite --port 5199' || true
